-- Buy box versions and the investor import (T319), generated by Prisma from schema.prisma, plus
-- the rules Prisma cannot express, hand-written at the end: buy box versions are append-only, and
-- a row result names its investor unless it was rejected, when it gives the reason instead.

-- CreateEnum
CREATE TYPE "ImportRowOutcome" AS ENUM ('IMPORTED', 'UPDATED', 'REJECTED');

-- AlterTable
ALTER TABLE "Investor" ADD COLUMN     "externalRef" TEXT;

-- CreateTable
CREATE TABLE "BuyBoxVersion" (
    "id" TEXT NOT NULL,
    "buyBoxId" TEXT NOT NULL,
    "version" INTEGER NOT NULL,
    "snapshot" JSONB NOT NULL,
    "createdBy" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "BuyBoxVersion_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "ImportBatch" (
    "id" TEXT NOT NULL,
    "fileName" TEXT NOT NULL,
    "storageKey" TEXT NOT NULL,
    "jobId" TEXT,
    "totalRows" INTEGER,
    "imported" INTEGER NOT NULL DEFAULT 0,
    "updated" INTEGER NOT NULL DEFAULT 0,
    "rejected" INTEGER NOT NULL DEFAULT 0,
    "ignoredColumns" TEXT[],
    "error" TEXT,
    "createdBy" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "finishedAt" TIMESTAMP(3),

    CONSTRAINT "ImportBatch_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "ImportRowResult" (
    "id" TEXT NOT NULL,
    "batchId" TEXT NOT NULL,
    "rowNumber" INTEGER NOT NULL,
    "outcome" "ImportRowOutcome" NOT NULL,
    "reason" TEXT,
    "investorId" TEXT,

    CONSTRAINT "ImportRowResult_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "BuyBoxVersion_buyBoxId_version_key" ON "BuyBoxVersion"("buyBoxId", "version");

-- CreateIndex
CREATE UNIQUE INDEX "ImportBatch_jobId_key" ON "ImportBatch"("jobId");

-- CreateIndex
CREATE UNIQUE INDEX "ImportRowResult_batchId_rowNumber_key" ON "ImportRowResult"("batchId", "rowNumber");

-- CreateIndex
CREATE UNIQUE INDEX "Investor_externalRef_key" ON "Investor"("externalRef");

-- AddForeignKey
ALTER TABLE "BuyBoxVersion" ADD CONSTRAINT "BuyBoxVersion_buyBoxId_fkey" FOREIGN KEY ("buyBoxId") REFERENCES "BuyBox"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ImportBatch" ADD CONSTRAINT "ImportBatch_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "Job"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ImportRowResult" ADD CONSTRAINT "ImportRowResult_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "ImportBatch"("id") ON DELETE CASCADE ON UPDATE CASCADE;


-- CreateTrigger (hand-written): buy box versions are history (refuse_append_only_change comes
-- from the publish-fields migration).
CREATE TRIGGER "BuyBoxVersion_append_only" BEFORE UPDATE OR DELETE ON "BuyBoxVersion"
    FOR EACH ROW EXECUTE FUNCTION "refuse_append_only_change"();

-- AddCheck (hand-written): a rejected row says why and names no investor; any other names one.
ALTER TABLE "ImportRowResult" ADD CONSTRAINT "ImportRowResult_outcome_check" CHECK (
    ("outcome" = 'REJECTED' AND "reason" IS NOT NULL AND "investorId" IS NULL)
    OR ("outcome" <> 'REJECTED' AND "reason" IS NULL AND "investorId" IS NOT NULL)
);
